import readline from 'node:readline';import {spawn} from 'node:child_process';
for await(const line of readline.createInterface({input:process.stdin})){const r=JSON.parse(line);if(r.task==='log'){const fs=await import('node:fs/promises');while(true){try{await fs.access(r.params.waitFor);break;}catch{await new Promise(resolve=>setTimeout(resolve,5));}}process.stderr.write('log write fails\n');setInterval(()=>{},1000);}else if(r.task==='unicode'){const b=Buffer.from(JSON.stringify({version:1,id:r.id,type:'result',data:{value:'âm thanh 🐬'}})+'\n'),cut=b.findIndex(v=>v>127)+1;process.stdout.write(b.subarray(0,cut));await new Promise(resolve=>setTimeout(resolve,25));process.stdout.write(b.subarray(cut));}else if(r.task==='bad'){console.log('not-json');}else if(r.task==='hang'){setInterval(()=>{},1000);}else if((r.task==='child'||r.task==='orphan')){const child=spawn(process.execPath,['-e','setInterval(()=>{},1000)'],{stdio:r.task==='orphan'?['ignore',process.stdout,process.stderr]:'ignore'});process.stderr.write('child='+child.pid+'\n');if(r.task==='orphan')process.stderr.write('leader='+process.pid+'\n');if(r.task==='orphan')setTimeout(()=>process.exit(0),10);setInterval(()=>{},1000);}else if(r.task==='fail'){process.exitCode=7;}else{console.log(JSON.stringify({version:1,id:r.id,type:'result',data:{value:r.params?.value??42}}));}}
